-- The ledger is append-only. A row can be pushed again unchanged (a retry
-- after a lost reply is harmless and ignored); any change or delete is
-- refused. Undoing something means appending a reversing row.
create or replace function public.ledger_append_only() returns trigger
language plpgsql as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'ledger rows cannot be deleted' using errcode = '23000';
  end if;
  if (to_jsonb(new) - 'server_seq' - 'dirty') is distinct from
     (to_jsonb(old) - 'server_seq' - 'dirty') then
    raise exception 'ledger rows cannot be changed' using errcode = '23000';
  end if;
  return null; -- identical re-push: skip the write entirely
end;
$$;

create trigger ledger_entries_append_only before update or delete on public.ledger_entries
  for each row execute function public.ledger_append_only();
create trigger ledger_payments_append_only before update or delete on public.ledger_payments
  for each row execute function public.ledger_append_only();
create trigger ledger_allocations_append_only before update or delete on public.ledger_allocations
  for each row execute function public.ledger_append_only();

